UPDATE albums
SET name = #{name}, description = #{description}, cover_image = #{coverImage}, updated_at = NOW()
WHERE id = #{id}

UPDATE albums
SET media_count = COALESCE(media_count, 0) + 1, updated_at = NOW()
WHERE id = #{id}

UPDATE albums
SET media_count = GREATEST(COALESCE(media_count, 0) - 1, 0), updated_at = NOW()
WHERE id = #{id}
